Object.assign(SNIP,{"l23func": "string s = \"lap trinh C++\";\ns.substr(4, 5)        // \"trinh\"  (từ vị trí 4, lấy 5 ký tự)\ns.find(\"trinh\")       // 4       (vị trí xuất hiện đầu tiên)\ns.find(\"java\")        // string::npos (không tìm thấy)\ns.erase(0, 4);        // xóa 4 ký tự từ vị trí 0 → \"trinh C++\"\ns.insert(0, \"Hoc \");  // chèn vào vị trí 0 → \"Hoc trinh C++\"\ns.push_back('!');     // thêm một ký tự vào cuối", "l23char": "char c = 'g';\nif (c >= 'a' && c <= 'z') c = c - 'a' + 'A';   // chữ thường → chữ hoa: 'G'\nchar d = '7';\nint so = d - '0';                               // ký tự số → giá trị số: 7", "l23idx": "string s = \"Hello\";\ncout << s[0];          // 'H'   (ký tự đầu)\ncout << s[s.size() - 1]; // 'o' (ký tự cuối)\ns[0] = 'J';            // s thành \"Jello\"\nfor (char c : s) cout << c << '-';   // J-e-l-l-o-"});PRESET_NOTES["l23"]={"Ví dụ: Duyệt từng ký tự": "Chuỗi \"Hello\" có 5 ký tự, chỉ số 0..4. (int)s.size() ép về int để so sánh với i mà không bị cảnh báo -Wsign-compare.", "Ví dụ: Đếm chữ hoa, chữ thường, chữ số": "getline đọc cả dòng (có dấu cách). for (char c : s) đi qua từng ký tự; so sánh với khoảng 'A'..'Z', 'a'..'z', '0'..'9' nhờ mã ký tự liên tiếp.", "Ví dụ: Đổi sang chữ hoa": "s[i] - 'a' + 'A' đổi chữ thường thành chữ hoa (lệch nhau 32 trong bảng mã). Dấu cách và chữ số giữ nguyên.", "Ví dụ: Đảo ngược chuỗi": "Giống đảo ngược mảng: hai chỉ số từ hai đầu tiến vào giữa, đổi chỗ từng cặp ký tự.", "Ví dụ: substr, find, erase, insert": "substr(4, 5) lấy 5 ký tự từ vị trí 4. find trả về vị trí, hoặc string::npos nếu không có. erase, insert, += sửa trực tiếp chuỗi s.", "Ví dụ: Đếm từ trong một dòng": "Một từ bắt đầu ở vị trí i khi s[i] không phải dấu cách và ký tự trước nó là dấu cách (hoặc i là đầu chuỗi). Cách này đúng cả khi có nhiều dấu cách liền nhau.", "Ví dụ: So sánh chuỗi": "So sánh theo thứ tự từ điển, từng ký tự theo mã ASCII: \"apple\" < \"apply\" vì 'e' < 'y'; \"Zoo\" < \"apple\" vì 'Z' (90) < 'a' (97).", "Ví dụ: toupper và isdigit": "Hàm của <cctype> trả về int. Gán vào s[i] (kiểu char) thì được chữ; nhưng cout << toupper('a') in số 65. isdigit(c) khác 0 khi c là chữ số.", "Bẫy: chữ có dấu chiếm nhiều byte": "\"Việt\" có 4 chữ nhưng 6 byte: chữ \"ệ\" mã hóa UTF-8 chiếm 3 byte. string đếm byte, không đếm chữ.", "Lỗi: at() ngoài chuỗi": "s.at(i) kiểm tra chỉ số: chỉ số không hợp lệ thì ném ngoại lệ out_of_range và chương trình dừng (máy thật cũng vậy). s[i] thì không kiểm tra."};EX_HINTS["l23"]=[["Dùng getline(cin, s) vì dòng có dấu cách.", "Đổi ký tự về chữ thường trước khi so sánh để không phải viết 10 điều kiện.", "Có thể dùng chuỗi \"aeiou\" và kiểm tra find(c) != string::npos."], ["Ký tự s[i] là đầu từ khi i == 0 hoặc s[i - 1] là dấu cách.", "Chỉ đổi khi ký tự đó là chữ thường: s[i] - 'a' + 'A'.", "Kiểm tra i == 0 TRƯỚC khi đọc s[i - 1] để không truy cập s[-1]."], ["Đổi cả chuỗi về chữ thường trước.", "Hai chỉ số i từ đầu, j từ cuối; khác nhau ở một cặp là đủ kết luận NO.", "Chỉ cần so tới giữa chuỗi (i < j)."]];
