const P23=[{label:"Ví dụ: Duyệt từng ký tự",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s = \"Hello\";\n    cout << \"Do dai: \" << s.size() << \"\\n\";\n    for (int i = 0; i < (int)s.size(); i++) {\n        cout << i << \": \" << s[i] << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i"]}]},{label:"Ví dụ: Đếm chữ hoa, chữ thường, chữ số",input:"Hoc C++ tu 2026!",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int hoa = 0, thuong = 0, so = 0, khac = 0;\n    for (char c : s) {\n        if (c >= 'A' && c <= 'Z') hoa++;\n        else if (c >= 'a' && c <= 'z') thuong++;\n        else if (c >= '0' && c <= '9') so++;\n        else khac++;\n    }\n    cout << hoa << \" \" << thuong << \" \" << so << \" \" << khac << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s"},{type:"vars",names:["c","hoa","thuong","so","khac"]}]},{label:"Ví dụ: Đổi sang chữ hoa",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s = \"xin chao 2026\";\n    for (int i = 0; i < (int)s.size(); i++) {\n        if (s[i] >= 'a' && s[i] <= 'z') {\n            s[i] = s[i] - 'a' + 'A';\n        }\n    }\n    cout << s << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i"]}]},{label:"Ví dụ: Đảo ngược chuỗi",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s = \"abcdef\";\n    int i = 0, j = s.size() - 1;\n    while (i < j) {\n        char tam = s[i];\n        s[i] = s[j];\n        s[j] = tam;\n        i++;\n        j--;\n    }\n    cout << s << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i","j"],range:["i","j"]}]},{label:"Ví dụ: substr, find, erase, insert",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s = \"lap trinh C++\";\n    cout << s.substr(4, 5) << \"\\n\";\n    cout << s.find(\"trinh\") << \"\\n\";\n    if (s.find(\"java\") == string::npos) cout << \"khong co java\\n\";\n    s.erase(0, 4);\n    s.insert(0, \"Hoc \");\n    s += \" that vui\";\n    cout << s << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s"}]},{label:"Ví dụ: Đếm từ trong một dòng",input:"  hoc   lap trinh  that vui ",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int dem = 0;\n    for (int i = 0; i < (int)s.size(); i++) {\n        bool batDauTu = s[i] != ' ' && (i == 0 || s[i - 1] == ' ');\n        if (batDauTu) dem++;\n    }\n    cout << \"So tu: \" << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i"]}]},{label:"Ví dụ: So sánh chuỗi",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string a = \"apple\", b = \"apply\", c = \"Zoo\";\n    cout << (a < b) << \" \" << (c < a) << \" \" << (a == \"apple\") << \"\\n\";\n    string ten = \"An\";\n    ten = ten + \" \" + \"Nguyen\";\n    cout << ten << \" (\" << ten.size() << \" ky tu)\\n\";\n    return 0;\n}"},{label:"Ví dụ: toupper và isdigit",input:"",code:"#include <iostream>\n#include <string>\n#include <cctype>\nusing namespace std;\n\nint main() {\n    string s = \"ma so 7B\";\n    int tongSo = 0;\n    for (int i = 0; i < (int)s.size(); i++) {\n        if (isdigit(s[i])) tongSo += s[i] - '0';\n        s[i] = toupper(s[i]);\n    }\n    cout << s << \" \" << tongSo << \"\\n\";\n    cout << toupper('a') << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i"]}]},{label:"Bẫy: chữ có dấu chiếm nhiều byte",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string a = \"Viet\", b = \"Việt\";\n    cout << a.size() << \" \" << b.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"b"}]},{label:"Lỗi: at() ngoài chuỗi",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s = \"abc\";\n    cout << s.at(1) << \"\\n\";\n    cout << s.at(5) << \"\\n\";\n    return 0;\n}"}];
